\begin{tikzpicture}[font=\sffamily, scale=1.1]

    % --- Phospholipid Bilayer parameters ---
    % We will draw a representative set of phospholipids in a bilayer.
    % Let's define a helper macro or just draw them carefully.
    % Outer leaflet (top): heads at y = 1.5, tails going down to y = 0.2
    % Inner leaflet (bottom): heads at y = -1.5, tails going up to y = -0.2

    % Let's draw the background / general membrane zone
    \draw[white, fill=white] (-4,-2.5) rectangle (4,2.5);

    % --- Tail and Head drawing ---
    % We need:
    % - Phospholipids
    % - A transmembrane protein with glycoprotein (carbohydrate chain A)
    % - A channel protein with a pore (channel C)
    % - Cholesterol (D)
    % - Phospholipid head (B)
    % - Phospholipid tails (E)

    % Let's place proteins first so we can draw phospholipids around them.
    % Transmembrane glycoprotein at left: x from -2.2 to -1.0
    \begin{scope}[shift={(-1.6,0)}]:
        % Protein body
        \draw[thick, fill=gray!15] (-0.7,-1.5) rectangle (0.7,1.5);
        % Some inner texture / smooth rounded look
        \draw[thick, rounded corners=3pt, fill=gray!25] (-0.7,-1.5) rectangle (0.7,1.5);

        % Carbohydrate chain (A) on top (glycoprotein)
        \begin{scope}[shift={(0,1.5)}, thick]
            \draw (0,0) circle (0.1);
            \draw (0,0.2) circle (0.1);
            \draw (0.15,0.35) circle (0.1);
            \draw (-0.15,0.35) circle (0.1);
            \draw (0,0.5) circle (0.1);
            % connections
            \draw (0,0.1) -- (0,0.1);
            \draw (0,0.1) -- (0,0.1);
        \end{scope}
    \end{scope}

    % Channel protein at right: x from 1.0 to 2.4, split into two parts with a gap in the middle
    \begin{scope}[shift={(1.7,0)}]
        % Left half of channel
        \draw[thick, rounded corners=3pt, fill=gray!30] (-0.7,-1.5) rectangle (-0.1,1.5);
        % Right half of channel
        \draw[thick, rounded corners=3pt, fill=gray!30] (0.1,-1.5) rectangle (0.7,1.5);
        % Central pore (C will point here)
        \coordinate (pore) at (0,0);
    \end{scope}

    % --- Draw Phospholipids ---
    % Function to draw a single phospholipid
    % #1: x, #2: y, #3: rotation/flip (1 for top, -1 for bottom)
    \newcommand{\phospholipid}[2]{
        % top layer (y = 1.5, tails down to 0)
        \draw[thick] (#1, 1.5) circle (0.2cm);
        \draw[thick] (#1-0.08, 1.3) -- (#1-0.12, 0.4);
        \draw[thick] (#1+0.08, 1.3) -- (#1+0.12, 0.4);
        % slight wiggle to tails
        \draw[thick] (#1-0.12,0.4) arc (180:360:0.04 and 0.2);
        \draw[thick] (#1+0.12,0.4) arc (0:180:0.04 and 0.2);
    }

    \newcommand{\phospholipidbot}[2]{
        % bottom layer (y = -1.5, tails up to 0)
        \draw[thick] (#1, -1.5) circle (0.2cm);
        \draw[thick] (#1-0.08, -1.3) -- (#1-0.12, -0.4);
        \draw[thick] (#1+0.08, -1.3) -- (#1+0.12, -0.4);
        \draw[thick] (#1-0.12,-0.4) arc (180:360:0.04 and -0.2);
        \draw[thick] (#1+0.12,-0.4) arc (0:180:0.04 and -0.2);
    }

    % Top row phospholipids (avoiding protein zones: approx -2.5 to -0.8 and 0.8 to 2.8)
    \foreach \x in {-3.5, -3.0, -2.5, 0.2, 0.7, 2.7, 3.2, 3.7} {
        \phospholipid{\x}{1.5}
    }

    % Bottom row phospholipids
    \foreach \x in {-3.5, -3.0, -2.5, 0.2, 0.7, 2.7, 3.2, 3.7} {
        \phospholipidbot{\x}{-1.5}
    }

    % --- Cholesterol (D) ---
    % Sits among the tails in one layer (e.g., top right or left)
    \begin{scope}[shift={(-2.8, 0.6)}, rotate=25]
        \draw[thick, fill=gray!40] (0,0) polygon (0,0, 0.3,0.1, 0.4,0.4, 0.2,0.6, -0.1,0.5, -0.2,0.2);
        \coordinate (cholesterol) at (0,0.3);
    \end{scope}

    % --- Labels and Label Lines ---

    % A: Carbohydrate chain
    \draw[thick, -latex] (-3.2, 2.5) node[left] {A} -- (-1.6, 2.2);

    % B: Phospholipid head
    \coordinate (headB) at (-3.5, 1.7);
    \draw[thick, -latex] (-4.5, 1.5) node[left] {B} -- (headB);

    % C: Channel through the channel protein
    \coordinate (channelC) at (1.7, 0);
    \draw[thick, -latex] (3.5, 0.8) node[right] {C} -- (channelC);

    % D: Cholesterol
    \coordinate (cholD) at (-2.7, 0.7);
    \draw[thick, -latex] (-4.5, -0.5) node[left] {D} -- (cholD);

    % E: Tails
    \coordinate (tailE) at (3.0, 0.3);
    \draw[thick, -latex] (4.5, -1.2) node[right] {E} -- (tailE);

    % --- Caption ---
    \node at (0, -2.5) {Fig. 8.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.1]

    % --- Background / Canvas ---
    \draw[white, fill=white] (-4.8,-2.8) rectangle (4.8,2.8);

    % --- Proteins ---
    % Transmembrane glycoprotein at left: x from -2.3 to -0.9
    \begin{scope}[shift={(-1.6,0)}]
        \draw[thick, rounded corners=3pt, fill=gray!25] (-0.7,-1.5) rectangle (0.7,1.5);

        % Carbohydrate chain (A) on top (glycoprotein) - small chain of circles
        \begin{scope}[shift={(0,1.5)}, thick]
            \draw[fill=white] (0,0) circle (0.09);
            \draw[fill=white] (0,0.2) circle (0.09);
            \draw[fill=white] (0.15,0.36) circle (0.09);
            \draw[fill=white] (-0.15,0.36) circle (0.09);
            \draw[fill=white] (0,0.52) circle (0.09);
        \end{scope}
    \end{scope}

    % Channel protein at right: split into two parts with a gap in the middle
    \begin{scope}[shift={(1.7,0)}]
        \draw[thick, rounded corners=3pt, fill=gray!30] (-0.7,-1.5) rectangle (-0.15,1.5);
        \draw[thick, rounded corners=3pt, fill=gray!30] (0.15,-1.5) rectangle (0.7,1.5);
    \end{scope}

    % --- Draw Phospholipids ---
    % Custom macro for top phospholipid
    \newcommand{\phospholipidtop}[1]{
        \draw[thick, fill=white] (#1, 1.4) circle (0.18cm);
        \draw[thick] (#1-0.07, 1.22) -- (#1-0.09, 0.3);
        \draw[thick] (#1+0.07, 1.22) -- (#1+0.09, 0.3);
        \draw[thick] (#1-0.09,0.3) .. controls (#1-0.15,0.05) and (#1-0.03,-0.05) .. (#1-0.09,-0.3);
        \draw[thick] (#1+0.09,0.3) .. controls (#1+0.03,0.05) and (#1+0.15,-0.05) .. (#1+0.09,-0.3);
    }

    % Custom macro for bottom phospholipid
    \newcommand{\phospholipidbot}[1]{
        \draw[thick, fill=white] (#1, -1.4) circle (0.18cm);
        \draw[thick] (#1-0.07, -1.22) -- (#1-0.09, -0.3);
        \draw[thick] (#1+0.07, -1.22) -- (#1+0.09, -0.3);
        \draw[thick] (#1-0.09,-0.3) .. controls (#1-0.15,-0.05) and (#1-0.03,0.05) .. (#1-0.09,0.3);
        \draw[thick] (#1+0.09,-0.3) .. controls (#1+0.03,-0.05) and (#1+0.15,0.05) .. (#1+0.09,0.3);
    }

    % Top and bottom row phospholipids
    \foreach \x in {-3.6, -3.1, -2.6, 0.3, 0.8, 2.7, 3.2, 3.7} {
        \phospholipidtop{\x}
        \phospholipidbot{\x}
    }

    % --- Cholesterol (D) ---
    % Sits among the tails in one layer
    \begin{scope}[shift={(-2.8, 0.6)}, rotate=20]
        \draw[thick, fill=gray!40] (0,0) rectangle (0.35, 0.7);
        \draw[thick, fill=gray!40] (0.35, 0.1) rectangle (0.55, 0.6);
    \end{scope}

    % --- Labels and Label Lines ---

    % A: Carbohydrate chain
    \draw[thick, -latex] (-3.2, 2.3) node[left] {A} -- (-1.6, 1.95);

    % B: Phospholipid head
    \coordinate (headB) at (-3.6, 1.4);
    \draw[thick, -latex] (-4.5, 1.4) node[left] {B} -- (headB);

    % C: Channel through the channel protein
    \coordinate (channelC) at (1.7, 0);
    \draw[thick, -latex] (3.4, 0.6) node[right] {C} -- (channelC);

    % D: Cholesterol
    \coordinate (cholD) at (-2.7, 0.75);
    \draw[thick, -latex] (-4.5, -0.2) node[left] {D} -- (cholD);

    % E: Tails
    \coordinate (tailE) at (3.0, 0.3);
    \draw[thick, -latex] (4.5, -1.0) node[right] {E} -- (tailE);

    % --- Caption ---
    \node at (0, -2.5) {Fig. 8.1};

\end{tikzpicture}

